{
  "name": "RP2040红外收发模块",
  "name_en": "RP2040 Infrared Transceiver Module",
  "manufacturer": "",
  "description": "一款通过 USB 转串口与上位机通信的红外收发实验模块，能够发送预定义的红外脉冲时序并记录接收到的红外信号时序。适用于红外遥控协议验证、红外发射/接收实验、时序采集与嵌入式通信教学。",
  "description_en": "An infrared transmit/receive experimental module that communicates with a host computer over USB-UART. It can send predefined infrared pulse timing sequences and record received infrared signal timings. It is suitable for IR remote protocol testing, infrared transmission/reception experiments, timing capture, and embedded communication teaching.",
  "tag_hints": [
    "infrared transceiver",
    "IR remote protocol",
    "USB-UART communication",
    "timing sequence generation",
    "signal capture",
    "RP2040"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接红外收发模块",
      "description_en": "Connect to the infrared transceiver module."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开红外收发模块连接",
      "description_en": "Disconnect from the infrared transceiver module."
    },
    {
      "action_name": "auto-is_connect",
      "description": "查询红外收发模块是否已连接",
      "description_en": "Check whether the infrared transceiver module is connected."
    },
    {
      "action_name": "auto-send",
      "description": "发送红外脉冲时序信号",
      "description_en": "Send an infrared pulse timing sequence."
    },
    {
      "action_name": "auto-record",
      "description": "记录接收到的红外信号时序",
      "description_en": "Record the timing sequence of a received infrared signal."
    }
  ]
}

